<?php require_once __DIR__ . '/../../includes/layout.php'; require_login(); check_csrf(); if($_SERVER['REQUEST_METHOD']==='POST'){db()->prepare('UPDATE notifications SET is_read=1 WHERE user_id=?')->execute([$_SESSION['user_id']]); set_flash('success','Your notifications are marked as read.'); redirect('notifications.php');} render_header('Notifications'); ?><div class="page-title"><div><h1>Notifications</h1><p>System messages and alerts.</p></div></div><div class="panel"><h2 class="panel-title">Visit & document updates</h2><p><a href="<?= in_array(current_user()['role'],['Admin','Super Admin'],true)?'/Admin/Notifications':'/Queue/Notifications' ?>">Open queue reminders and document notifications →</a></p><p class="small text-muted">Review invitations to exchange visit times. An exchange happens only after both owners agree.</p><button class="btn btn-outline-primary" type="button" data-assistant-action="exchanges">View exchange invitations</button></div><form method="post" class="mb-3"><?= csrf_field() ?><button class="btn btn-outline-primary">Mark my notifications as read</button></form><div class="panel"><?php foreach(rows('SELECT * FROM notifications WHERE user_id=? OR user_id IS NULL ORDER BY created_at DESC',[$_SESSION['user_id']]) as $n): ?><div class="border-bottom py-3"><strong><?= e($n['title']) ?></strong><br><span><?= e($n['body']) ?></span><br><small class="text-muted"><?= e($n['created_at']) ?></small></div><?php endforeach; ?></div><?php render_footer(); ?>
